// Returns NULL if char not in font.
static inline const font_mb_glyph_t *font_mb_get(char c) {
    unsigned u = (unsigned char)c;
    if (u >= 128 || !font_mb[u].advance) return NULL;
    return &font_mb[u];
}

// Pixel width of a string.
static inline int font_mb_str_width(const char *s) {
    int w = 0;
    for (; *s; s++) {
        const font_mb_glyph_t *g = font_mb_get(*s);
        if (g) w += g->advance;
    }
    return w;
}
